# Makes the record file fixtures (stage 56 step 3): small real photos as a phone writes them, with
# location (GPS), camera and time metadata, an XMP packet and a comment, encoded by Pillow's own
# JPEG, PNG and WebP encoders, and written as base64 into photos.ts beside this file.
#
#   python3 -I packages/core/test/fixtures/record-files/make.py
#
# Needs Pillow (12 or later). The output is committed; run this only to change the fixtures.
import base64
import io
import pathlib

from PIL import Image, ImageDraw
from PIL.PngImagePlugin import PngInfo

HERE = pathlib.Path(__file__).parent

XMP = (
    b'<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>'
    b'<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">'
    b'<rdf:Description xmlns:exif="http://ns.adobe.com/exif/1.0/" exif:GPSLatitude="33,52.1234S" '
    b'exif:GPSLongitude="151,12.5678E"/></rdf:RDF></x:xmpmeta><?xpacket end="w"?>'
)


def picture() -> Image.Image:
    image = Image.new("RGB", (48, 32), (200, 120, 40))
    draw = ImageDraw.Draw(image)
    draw.rectangle([4, 4, 20, 28], fill=(30, 90, 200))
    draw.ellipse([26, 6, 44, 26], fill=(240, 240, 240))
    return image


def exif() -> Image.Exif:
    data = Image.Exif()
    data[0x010F] = "PhoneMakerCo"  # Make
    data[0x0110] = "PocketCam 12"  # Model
    data[0x0112] = 6  # Orientation: rotate 90 to stand upright
    data[0x0132] = "2026:11:20 09:41:00"  # DateTime
    gps = data.get_ifd(0x8825)
    gps[1] = "S"  # GPSLatitudeRef
    gps[2] = (33.0, 52.0, 7.4)  # GPSLatitude
    gps[3] = "E"  # GPSLongitudeRef
    gps[4] = (151.0, 12.0, 34.1)  # GPSLongitude
    return data


def encode(fmt: str, **options) -> bytes:
    out = io.BytesIO()
    picture().save(out, fmt, **options)
    return out.getvalue()


# A PNG also carries a text chunk naming the place, as some editors write.
png_info = PngInfo()
png_info.add_text("Location", "12 Example St, -33.8687, 151.2093")

files = {
    "GPS_JPEG": encode("JPEG", exif=exif(), xmp=XMP, comment=b"Taken at 12 Example St", quality=90),
    "GPS_PNG": encode("PNG", exif=exif(), pnginfo=png_info),
    "GPS_WEBP": encode("WEBP", exif=exif(), xmp=XMP, quality=80),
}

lines = [
    "// Generated by make.py beside this file: real photos as Pillow's encoders write them, carrying",
    "// location (GPS), camera and time metadata. Do not edit by hand.",
    "",
]
for name, data in files.items():
    lines.append(f'export const {name} = "{base64.b64encode(data).decode()}";')
(HERE / "photos.ts").write_text("\n".join(lines) + "\n")
for name, data in files.items():
    print(name, len(data))
